template:
@php
    // The switch says where the headings are; a block saved before it had a value lists the page, as new ones do.
    $own = $source === 'text';
    $text = $own && is_string($body) ? trim($body) : '';
    $levels = (string) $depth === '2' ? 2 : 3;
    $place = $side === 'start' ? 'start' : 'end';
    $title = $heading ? wx_text($heading)->plain() : '';
@endphp
@if (! $own)
<section class="b-toc" data-wx-block="toc">
    <x-webx-toc :depth="$levels" :title="$title ?: null" />
</section>
@elseif ($text !== '')
<section class="b-toc b-toc--text" data-wx-block="toc">
    <x-webx-toc :depth="$levels" :title="$title ?: null" :side="$place"><div class="b-toc__body">{!! $text !!}</div></x-webx-toc>
</section>
@endif
